question.solution:
def compress(s):
    if not s:
        return ''
    parts = []
    current = s[0]
    count = 1
    for ch in s[1:]:
        if ch == current:
            count += 1
        else:
            parts.append(current + str(count))
            current = ch
            count = 1
    parts.append(current + str(count))
    return ''.join(parts)

print(compress('aaabbc'))
print(compress(''))
print(compress('abc'))
